  ]$relations$::jsonb;
  expected_schema constant jsonb := $schema${"acl":["postgres=UC/postgres"],"owner":"postgres","identity":"ingestion_generation_evidence","anon_usage":false,"default_acl":[],"service_role_usage":false,"authenticated_usage":false}$schema$::jsonb;
begin
  if current_user <> 'postgres' then
    failures := array_append(failures, 'migration role must be postgres');
  end if;

  for required in select value from jsonb_array_elements(expected_functions)
  loop
    select 
jsonb_build_object(
  'identity', p.oid::regprocedure::text,
  'name', n.nspname || '.' || p.proname,
  'owner', pg_get_userbyid(p.proowner),
  'security_definer', p.prosecdef,
  'config', (select coalesce(jsonb_agg(x order by x), '[]'::jsonb) from unnest(p.proconfig) x),
  'acl', (select jsonb_agg(x::text order by x::text) from unnest(coalesce(p.proacl, acldefault('f',p.proowner))) x),
  'source_md5', md5(p.prosrc),
  'definition_md5', md5(regexp_replace(regexp_replace(regexp_replace(pg_get_functiondef(p.oid), '/\*.*?\*/', '', 'gs'), '--[^\n]*', '', 'g'), '\s+', '', 'g')),
  'anon_execute', has_function_privilege('anon',p.oid,'EXECUTE'),
  'authenticated_execute', has_function_privilege('authenticated',p.oid,'EXECUTE')
)
      into actual
    from pg_proc p join pg_namespace n on n.oid=p.pronamespace
    where p.prokind='f' and p.oid::regprocedure::text=required->>'identity';
    if actual is distinct from required then
      failures := array_append(failures, 'function contract: ' || (required->>'identity'));
    end if;
    if actual->'anon_execute' is distinct from 'false'::jsonb
       or ((required->>'identity') not in (
             'public.is_visible_document_page(uuid,uuid,text)',
             'public.admit_administrator_document(jsonb,jsonb,boolean)')
           and actual->'authenticated_execute' is distinct from 'false'::jsonb) then
      failures := array_append(failures, 'public wrapper access: ' || (required->>'identity'));
    end if;
  end loop;

  -- Catch additional overloads of affected names, including an accidentally
  -- restored legacy wrapper. Private functions all belong to this cutover.
  for actual in
    select jsonb_build_object('identity',p.oid::regprocedure::text)
    from pg_proc p join pg_namespace n on n.oid=p.pronamespace
    where p.prokind='f' and (
      n.nspname='ingestion_generation_evidence'
      or n.nspname || '.' || p.proname in (
        select value->>'name' from jsonb_array_elements(expected_functions)))
      and not exists(select 1 from jsonb_array_elements(expected_functions) e
        where e->>'identity'=p.oid::regprocedure::text)
  loop
    failures := array_append(failures, 'unexpected managed function: ' || (actual->>'identity'));
  end loop;

  for required in select value from jsonb_array_elements(expected_relations)
  loop
    select 
jsonb_build_object(
  'identity', n.nspname || '.' || c.relname,
  'owner', pg_get_userbyid(c.relowner), 'kind', c.relkind,
  'rls_enabled', c.relrowsecurity, 'rls_forced', c.relforcerowsecurity,
  'acl', (select jsonb_agg(x::text order by x::text) from unnest(coalesce(c.relacl, acldefault('r',c.relowner))) x),
  'columns_md5', md5(coalesce((
    select jsonb_agg(jsonb_build_object('name',a.attname,'type',format_type(a.atttypid,a.atttypmod),
      'not_null',a.attnotnull,'identity',a.attidentity,'generated',a.attgenerated,
      'collation',case when a.attcollation = 0 then null else a.attcollation::regcollation::text end,
      'default',pg_get_expr(d.adbin,d.adrelid),
      'acl',(select jsonb_agg(x::text order by x::text) from unnest(a.attacl) x)) order by a.attname)
    from pg_attribute a left join pg_attrdef d on d.adrelid=a.attrelid and d.adnum=a.attnum
    where a.attrelid=c.oid and a.attnum>0 and not a.attisdropped
  ),'[]'::jsonb)::text),
  'constraints', coalesce((select jsonb_agg(jsonb_build_object(
    'name',con.conname,'definition_md5',md5(regexp_replace(pg_get_constraintdef(con.oid),'\s+','','g')),
    'validated',con.convalidated,'deferrable',con.condeferrable,'deferred',con.condeferred)
    order by con.conname) from pg_constraint con where con.conrelid=c.oid),'[]'::jsonb),
  'indexes', coalesce((select jsonb_agg(jsonb_build_object(
    'name',ni.nspname || '.' || ci.relname,
    'definition_md5',md5(regexp_replace(pg_get_indexdef(i.indexrelid),'\s+','','g')),
    'valid',i.indisvalid,'ready',i.indisready,'live',i.indislive)
    order by ci.relname) from pg_index i join pg_class ci on ci.oid=i.indexrelid
    join pg_namespace ni on ni.oid=ci.relnamespace where i.indrelid=c.oid),'[]'::jsonb),
  'triggers',coalesce((select jsonb_agg(jsonb_build_object(
    'name',t.tgname,'enabled',t.tgenabled,'definition_md5',md5(regexp_replace(pg_get_triggerdef(t.oid),'\s+','','g')))
    order by t.tgname) from pg_trigger t where t.tgrelid=c.oid and not t.tgisinternal),'[]'::jsonb),
  'policies_md5', md5(coalesce((select jsonb_agg(jsonb_build_object(
    'name',pol.polname,'permissive',pol.polpermissive,'command',pol.polcmd,
    'roles',(select jsonb_agg(case when r=0 then 'public' else pg_get_userbyid(r) end
      order by case when r=0 then 'public' else pg_get_userbyid(r) end) from unnest(pol.polroles) r),
    'using',pg_get_expr(pol.polqual,pol.polrelid),'with_check',pg_get_expr(pol.polwithcheck,pol.polrelid))
    order by pol.polname) from pg_policy pol where pol.polrelid=c.oid),'[]'::jsonb)::text)
)
      into actual
    from pg_class c join pg_namespace n on n.oid=c.relnamespace
    where c.relkind in ('r','p') and n.nspname || '.' || c.relname=required->>'identity';
    if actual is distinct from required then
      failures := array_append(failures, 'relation contract: ' || (required->>'identity'));
    end if;
  end loop;

  for actual in
    select jsonb_build_object('identity',n.nspname || '.' || c.relname)
    from pg_class c join pg_namespace n on n.oid=c.relnamespace
    where n.nspname='ingestion_generation_evidence' and c.relkind in ('r','p')
      and not exists(select 1 from jsonb_array_elements(expected_relations) e
        where e->>'identity'=n.nspname || '.' || c.relname)
  loop
    failures := array_append(failures, 'unexpected managed relation: ' || (actual->>'identity'));
  end loop;

  select 
jsonb_build_object(
  'identity', n.nspname,'owner',pg_get_userbyid(n.nspowner),
  'acl',(select jsonb_agg(x::text order by x::text) from unnest(coalesce(n.nspacl,acldefault('n',n.nspowner))) x),
  'default_acl',coalesce((select jsonb_agg(jsonb_build_object(
    'owner',pg_get_userbyid(d.defaclrole),'kind',d.defaclobjtype,
    'acl',(select jsonb_agg(x::text order by x::text) from unnest(d.defaclacl) x))
    order by pg_get_userbyid(d.defaclrole),d.defaclobjtype) from pg_default_acl d where d.defaclnamespace=n.oid),'[]'::jsonb),
  'anon_usage',has_schema_privilege('anon',n.oid,'USAGE'),
  'authenticated_usage',has_schema_privilege('authenticated',n.oid,'USAGE'),
  'service_role_usage',has_schema_privilege('service_role',n.oid,'USAGE')
)
    into actual
  from pg_namespace n where n.nspname='ingestion_generation_evidence';
  if actual is distinct from expected_schema then
    failures := array_append(failures, 'private schema owner/ACL/default privileges');
  end if;
  if actual->'anon_usage' is distinct from 'false'::jsonb
     or actual->'authenticated_usage' is distinct from 'false'::jsonb
     or actual->'service_role_usage' is distinct from 'false'::jsonb then
    failures := array_append(failures, 'private schema USAGE denial');
  end if;

  if cardinality(failures)>0 then
    raise exception 'Managed ingestion historical reconciliation failed: %. No state was repaired or migration history changed.',
      array_to_string(failures, '; ');
  end if;
end
$migration$;
